    /// The composition property with the given name, among the properties
    /// of this class and of its generated bases that have a variant form.
    pub fn get_composition_property(name: &str) -> Option<&'static CompositionProperty> {
        if name == "Visible" {
            return Some(Self::id_of_visible_property().base());
        }
        if name == "Opacity" {
            return Some(Self::id_of_opacity_property().base());
        }
        if name == "ClipToBounds" {
            return Some(Self::id_of_clip_to_bounds_property().base());
        }
        if name == "Offset" {
            return Some(Self::id_of_offset_property().base());
        }
        if name == "Translation" {
            return Some(Self::id_of_translation_property().base());
        }
        if name == "Size" {
            return Some(Self::id_of_size_property().base());
        }
        if name == "AnchorPoint" {
            return Some(Self::id_of_anchor_point_property().base());
        }
        if name == "CenterPoint" {
            return Some(Self::id_of_center_point_property().base());
        }
        if name == "RotationAngle" {
            return Some(Self::id_of_rotation_angle_property().base());
        }
        if name == "Orientation" {
            return Some(Self::id_of_orientation_property().base());
        }
        if name == "Scale" {
            return Some(Self::id_of_scale_property().base());
        }
        if name == "AdornerIsClipped" {
            return Some(Self::id_of_adorner_is_clipped_property().base());
        }
        None
    }
